#include <iostream>
#include <nlohmann/json.hpp>
#include <nlohmann/json_view.hpp>

int main() {
    try {
        nlohmann::json j = {
            {"b_val", true},
            {"i_val", -42},
            {"u_val", 42},
            {"f_val", 3.14},
            {"arr", {1, 2, 3}},
            {"obj", {{"x", 1}}}
        };
        std::string s = j.dump();
        auto doc = nlohmann::json_document::parse(s);
        auto v = doc.root();
        nlohmann::json j2 = j;
        bool comp = (v == j2);
        std::cout << "View equals json: " << (comp ? "true" : "false") << std::endl;
    } catch (const std::exception& e) {
        std::cout << "Exception: " << e.what() << std::endl;
    }
    return 0;
}
